def transform(grid):
    bg = grid[0][0]
    divider = next(i for i, row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg)
    marker = next(v for row in grid[:divider] for v in row if v != bg)
    lower = grid[divider + 1:]
    counts = {}
    for row in lower:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    rare = min(counts, key=counts.get)
    replacement = (marker + 1) % 10
    return [[replacement if v == rare else v for v in row] for row in lower]
